/* A map tap or typed coordinates are an explicit, user-labelled pin. */
(() => {
  const before=renderTrip;
  renderTrip=function(){const markup=before(),t=trip();if(!t||!markup.includes('id="trip-map-add"'))return markup;const extra=`<details class="manual-pin" id="manual-pin"><summary>地图上选一点，自己命名</summary><p>点地图会把坐标填到这里；也可以手动填写。它只代表你确认的坐标，不自动声称是某个景点入口。</p><form id="manual-pin-form"><label class="field"><span>给这个点取名</span><input name="label" maxlength="70" placeholder="例如：想去的咖啡馆或集合点" required></label><div class="manual-pin-coords"><label class="field"><span>纬度</span><input name="lat" type="number" min="-90" max="90" step="any" required></label><label class="field"><span>经度</span><input name="lon" type="number" min="-180" max="180" step="any" required></label></div><button class="secondary full" type="submit">确认并加入这一天</button><p class="manual-pin-feedback" role="status"></p></form></details>`;return markup.replace('</form><ol class="trip-stop-list">',`</form>${extra}<ol class="trip-stop-list">`)};
  document.addEventListener('xiangye:map-coordinate',event=>{const box=document.getElementById('manual-pin');if(!box)return;box.open=true;box.querySelector('[name="lat"]').value=event.detail.lat.toFixed(6);box.querySelector('[name="lon"]').value=event.detail.lon.toFixed(6);box.querySelector('.manual-pin-feedback').textContent='已选择地图坐标。请给它命名并确认加入。';box.scrollIntoView({behavior:'smooth',block:'nearest'});box.querySelector('[name="label"]').focus()});
  document.addEventListener('submit',event=>{if(event.target.id!=='manual-pin-form')return;event.preventDefault();const t=trip(),form=event.target,day=t?.days?.[Math.max(0,Math.min(t.days.length-1,Number(state.mapDay)||0))];if(!t||!day)return;const data=new FormData(form),name=String(data.get('label')||'').trim(),lat=Number(data.get('lat')),lon=Number(data.get('lon'));const feedback=form.querySelector('.manual-pin-feedback');if(!name||!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180){feedback.textContent='请填写名称及有效的经纬度。';return}const city=t.destination||'',key=`${name}|${city}`;if(day.places.includes(key)){feedback.textContent='这一天已经有同名地点，请换一个名称或查看已有地图钉。';return}if(!t.destinationData){const base=getDestination(t);t.destinationData={...(base||{}),places:[...(base?.places||[])]}}t.destinationData.places||=[];let place=t.destinationData.places.find(p=>`${p.name}|${p.city||''}`===key);if(place&&Math.abs(Number(place.lat)-lat)+Math.abs(Number(place.lon)-lon)>0.00001){feedback.textContent='这份行程已有同名地点。请用不同名称区分两个位置。';return}if(!place){place={id:`manual:${uid()}`,name,city,kind:'自选坐标',summary:'这是旅行者自行确认的地图位置；地点性质、入口与开放信息尚未核实。',lat,lon,positionStatus:'用户选定坐标',sources:[],time:'自行安排',cost:0};t.destinationData.places.push(place)}day.places.push(key);saveTrip(t);state.tripMapPlaceId=place.id;render();notify('自选坐标已加入当天行程和地图。')});
})();
